const LMap={'en':['en','en-US','en-GB'],'fa':['fa','fa-IR'],'ar':['ar','ar-SA'],'ckb':['ckb','ku-ar'],'kmr':['kmr','ku-IR'],'ru':['ru'],'es':['es'],'fr':['fr'],'de':['de'],'zh':['zh']};
let LV=localStorage.getItem('jibLangL');
if(!LV||!CL[LV]){const nav=(navigator.language||'en').toLowerCase();LV='en';for(const c in LMap)if(LMap[c].some(x=>nav.indexOf(x)>=0)){LV=c;break}localStorage.setItem('jibLangL',LV)}
function setLV(code){LV=code;localStorage.setItem('jibLangL',LV);applyL();buildGrid()}
function buildGrid(){const g=document.getElementById('langGrid');g.innerHTML=Object.keys(LANGS).map(c=>`<div class="lang-btn ${c===LV?'active':''}" data-l="${c}"><span class="lf">${LANGS[c][0]}</span><span class="lt"><b>${LANGS[c][1]}</b></span></div>`).join('');g.querySelectorAll('.lang-btn').forEach(b=>b.onclick=()=>{setLV(b.dataset.l);document.getElementById('langModal').classList.remove('show')})}
function applyL(){const d=CL[LV]||CL.en;document.documentElement.lang=LV;document.documentElement.dir=(RTL.indexOf(LV)>=0)?'rtl':'ltr';document.querySelectorAll('[data-l8n]').forEach(el=>{const k=el.getAttribute('data-l8n');if(d[k]!=null)el.textContent=d[k]});const h1=document.getElementById('heroH1');if(h1&&d.h1)h1.innerHTML=d.h1;const ch=document.getElementById('ctaH1');if(ch&&d.ctaH)ch.innerHTML=d.ctaH;const fe=document.getElementById('feH1');if(fe&&d.feH)fe.innerHTML=d.feH;const lf=document.getElementById('langFlag');if(lf)lf.textContent=LANGS[LV][0];const lc=document.getElementById('langCode');if(lc)lc.textContent=LV.toUpperCase();const ll=document.getElementById('lblLang');if(ll)ll.textContent=d.ln}
document.getElementById('langBtn').addEventListener('click',()=>{buildGrid();document.getElementById('langModal').classList.add('show')});
document.getElementById('langModal').addEventListener('click',e=>{if(e.target.id==='langModal')document.getElementById('langModal').classList.remove('show')});
applyL();

if('serviceWorker' in navigator&&location.protocol.indexOf('http')===0){window.addEventListener('load',()=>{navigator.serviceWorker.register('sw.js').catch(()=>{})})}

